// === Récupération des items de la requête SQL ===
const allItems = $input.all().map(i => i.json);

// === Séparation en 2 sections ===
const sectionSemaine = allItems.filter(i => i.section === 'actu_semaine');
const sectionMois = allItems.filter(i => i.section === 'recap_mois');

// === Métadonnées du digest ===
const now = new Date();
const numeroSemaine = getISOWeek(now);
const annee = now.getFullYear();
const dateAffichage = now.toLocaleDateString('fr-FR', { 
  weekday: 'long', day: 'numeric', month: 'long', year: 'numeric' 
});
const periodeDebut = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const periodeFin = now;

// === Calculs agrégés ===
const totalArticles = allItems.length;
const coutTotal = allItems.reduce((sum, i) => sum + parseFloat(i.cout_euros || 0), 0);
const scoreMoyen = totalArticles > 0
  ? allItems.reduce((sum, i) => sum + parseFloat(i.score_priorite || 0), 0) / totalArticles
  : 0;

// === Helpers ===
function escapeHtml(str) {
  if (!str) return '';
  return String(str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function getISOWeek(date) {
  const d = new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate()));
  const dayNum = d.getUTCDay() || 7;
  d.setUTCDate(d.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}

function badgeCriticite(criticite) {
  const colors = {
    'critique': '#dc2626', // rouge
    'elevee':   '#ea580c', // orange
    'moyenne':  '#ca8a04', // jaune
    'faible':   '#65a30d'  // vert
  };
  const labels = {
    'critique': 'CRITIQUE',
    'elevee':   'ÉLEVÉE',
    'moyenne':  'MOYENNE',
    'faible':   'FAIBLE'
  };
  const color = colors[criticite] || '#6b7280';
  const label = labels[criticite] || criticite.toUpperCase();
  return `<span style="display:inline-block;padding:3px 8px;background:${color};color:#fff;font-size:10px;font-weight:bold;letter-spacing:0.5px;border-radius:3px;">${label}</span>`;
}

function formatArticle(item, index) {
  const dateArticle = new Date(item.date_publication).toLocaleDateString('fr-FR', {
    day: 'numeric', month: 'short', year: 'numeric'
  });

  // Citations
  let citationsHtml = '';
  if (item.citations && Array.isArray(item.citations) && item.citations.length > 0) {
    citationsHtml = '<div style="margin-top:12px;padding-left:12px;border-left:3px solid #e5e7eb;">';
    item.citations.forEach(c => {
      if (c && c.texte) {
        const verifIcon = c.verifiee ? '✓' : '?';
        const verifColor = c.verifiee ? '#16a34a' : '#ca8a04';
        citationsHtml += `
          <div style="margin:6px 0;font-size:13px;color:#4b5563;font-style:italic;">
            <span style="color:${verifColor};font-weight:bold;margin-right:4px;">${verifIcon}</span>
            « ${escapeHtml(c.texte)} »
            ${c.contexte ? `<div style="font-style:normal;font-size:11px;color:#6b7280;margin-top:2px;">${escapeHtml(c.contexte)}</div>` : ''}
          </div>`;
      }
    });
    citationsHtml += '</div>';
  }

  return `
    <div style="margin:24px 0;padding:16px;background:#fafafa;border:1px solid #e5e7eb;border-radius:6px;">
      <div style="margin-bottom:8px;">
        ${badgeCriticite(item.criticite)}
        <span style="margin-left:8px;font-size:11px;color:#6b7280;">${escapeHtml(item.source_nom)} — ${dateArticle}</span>
        <span style="float:right;font-size:11px;color:#6b7280;">Score : ${item.score_priorite}</span>
      </div>
      <h3 style="margin:8px 0;font-size:15px;color:#111827;line-height:1.4;">
        ${escapeHtml(item.titre)}
      </h3>
      <div style="margin:8px 0;font-size:13px;color:#374151;font-weight:500;">
        ${escapeHtml(item.tldr || '')}
      </div>
      <div style="margin:8px 0;font-size:13px;color:#4b5563;line-height:1.6;">
        ${escapeHtml(item.contenu_synthese || '').replace(/\n/g, '<br>')}
      </div>
      ${citationsHtml}
      <div style="margin-top:10px;font-size:11px;color:#6b7280;">
        <a href="${escapeHtml(item.url)}" style="color:#2563eb;text-decoration:none;">→ Source originale</a>
        &nbsp;·&nbsp;
        Confiance IA : ${(parseFloat(item.confiance || 0) * 100).toFixed(0)}%
        &nbsp;·&nbsp;
        ${item.citations_verifiees || 0} citation${(item.citations_verifiees || 0) > 1 ? 's' : ''} vérifiée${(item.citations_verifiees || 0) > 1 ? 's' : ''}
      </div>
    </div>`;
}

// === Construction du HTML ===
const articlesSemaineHtml = sectionSemaine.length > 0
  ? sectionSemaine.map(formatArticle).join('')
  : '<div style="padding:24px;text-align:center;color:#6b7280;font-style:italic;background:#fafafa;border-radius:6px;">Pas d\'actualité majeure cette semaine. Consulter le récap mensuel ci-dessous pour les sujets à retenir.</div>';

const articlesMoisHtml = sectionMois.length > 0
  ? sectionMois.map(formatArticle).join('')
  : '<div style="padding:24px;text-align:center;color:#6b7280;font-style:italic;">Aucun article complémentaire à signaler ce mois.</div>';

// === HTML COMPLET ===
const html = `<!DOCTYPE html>
<html lang="fr">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>VeilleGRC — Digest semaine ${numeroSemaine}</title>
</head>
<body style="margin:0;padding:0;background:#f3f4f6;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#111827;">
<div style="max-width:720px;margin:0 auto;padding:24px;background:#ffffff;">

  <!-- Header -->
  <div style="border-bottom:3px solid #1f2937;padding-bottom:16px;margin-bottom:24px;">
    <div style="font-size:11px;color:#6b7280;letter-spacing:1.5px;font-weight:bold;">VEILLEGRC — HEDGEWOOD CONSEIL</div>
    <h1 style="margin:8px 0;font-size:28px;color:#111827;font-weight:bold;">
      Digest hebdomadaire — Semaine ${numeroSemaine} / ${annee}
    </h1>
    <div style="font-size:13px;color:#4b5563;">${dateAffichage}</div>
  </div>

  <!-- Mention IA -->
  <div style="margin:16px 0;padding:12px;background:#eff6ff;border-left:3px solid #2563eb;font-size:12px;color:#1e3a8a;">
    <strong>⚠ Document généré automatiquement par IA.</strong>
    Synthèses produites par Claude Sonnet 4.6 à partir de sources institutionnelles publiques.
    Citations vérifiées automatiquement contre le contenu source.
    Avant diffusion : revue humaine systématique requise (POL-IA-001 §6).
  </div>

  <!-- Section 1 : Actualités de la semaine -->
  <h2 style="margin:32px 0 16px 0;padding-bottom:8px;border-bottom:1px solid #d1d5db;font-size:20px;color:#111827;">
    📰 Actualités de la semaine
    <span style="float:right;font-size:13px;color:#6b7280;font-weight:normal;">${sectionSemaine.length} entrée${sectionSemaine.length > 1 ? 's' : ''}</span>
  </h2>
  ${articlesSemaineHtml}

  <!-- Section 2 : Récap du mois -->
  <h2 style="margin:40px 0 16px 0;padding-bottom:8px;border-bottom:1px solid #d1d5db;font-size:20px;color:#111827;">
    📊 Récap du mois — Top par sévérité
    <span style="float:right;font-size:13px;color:#6b7280;font-weight:normal;">${sectionMois.length} entrée${sectionMois.length > 1 ? 's' : ''}</span>
  </h2>
  ${articlesMoisHtml}

  <!-- Footer -->
  <div style="margin-top:48px;padding-top:24px;border-top:1px solid #d1d5db;font-size:11px;color:#6b7280;line-height:1.6;">
    <strong>Métriques du digest :</strong><br>
    ${totalArticles} article${totalArticles > 1 ? 's' : ''} • Score moyen ${scoreMoyen.toFixed(2)} • Coût IA cumulé ${coutTotal.toFixed(4)} €<br><br>
    <strong>Sources institutionnelles :</strong> CERT-FR, ANSSI, CNIL<br>
    <strong>Conformité :</strong> ISO 27001, ISO 42001, RGPD, AI Act art.50<br><br>
    <em>VeilleGRC-Agent v1.0 — Pipeline Ingestion → Classification (Haiku 4.5) → Synthèse (Sonnet 4.6)</em>
  </div>

</div>
</body>
</html>`;

// === Sujet d'email pré-construit ===
const sujet = sectionSemaine.length > 0
  ? `[VeilleGRC] Digest S${numeroSemaine} — ${sectionSemaine.length} actu${sectionSemaine.length > 1 ? 's' : ''} + ${sectionMois.length} récap mensuel`
  : `[VeilleGRC] Digest S${numeroSemaine} — Récap mensuel (${sectionMois.length} entrées)`;

// === Métadonnées de pondération pour audit ===
const ponderationDetails = {
  formule_actu_semaine: 'poids_criticite × poids_fiabilite × poids_recence × confiance',
  formule_recap_mois: 'poids_criticite × confiance (récence neutralisée)',
  poids_criticite: { critique: 100, elevee: 50, moyenne: 20, faible: 5 },
  poids_fiabilite: { ANSSI: 1.0, CNIL: 1.0, CERT_FR: 1.0, autres: 0.6 },
  poids_recence: { '<1j': 1.0, '1-3j': 0.8, '4-7j': 0.5, '8-14j': 0.3, '>14j': 0.2 }
};

// === Article IDs pour stockage en base ===
const articleIds = allItems.map(i => i.article_id);

// === Sortie ===
return [{
  json: {
    type_digest: 'hebdo',
    periode_debut: periodeDebut.toISOString(),
    periode_fin: periodeFin.toISOString(),
    nb_articles_inclus: totalArticles,
    article_ids: articleIds,
    contenu: html,
    statut: 'genere',
    score_moyen: scoreMoyen,
    ponderation_details: ponderationDetails,
    cout_total_euros: coutTotal,
    sujet_email: sujet,
    nb_actu_semaine: sectionSemaine.length,
    nb_recap_mois: sectionMois.length
  }
}];

const digestInfo = $input.item.json;

const message = `
=== DIGEST GÉNÉRÉ AVEC SUCCÈS ===
ID base       : ${digestInfo.id}
Type          : ${digestInfo.type_digest}
Période       : ${digestInfo.periode_debut} → ${digestInfo.periode_fin}
Articles      : ${digestInfo.nb_articles_inclus}
Sujet email   : ${digestInfo.sujet_email}
Taille HTML   : ${digestInfo.taille_html_chars} caractères

ACTION REQUISE (humain) :
1. Extraire le HTML : SELECT contenu FROM digests WHERE id = ${digestInfo.id}
2. Relire et valider
3. Copier-coller dans le client mail
4. Envoyer aux destinataires

Conformité POL-IA-001 §6 : envoi non automatisé, validation humaine requise.
`;

console.log(message);

return {
  json: {
    digest_id: digestInfo.id,
    statut: 'prêt à valider',
    message: message,
    instructions_humain: [
      'Extraire le HTML avec : SELECT contenu FROM digests WHERE id = ' + digestInfo.id,
      'Relire et valider le contenu',
      'Copier-coller dans le client mail',
      'Envoyer aux destinataires'
    ]
  }
};
